import threading, time
from collections import defaultdict

class PubSub:
    """In-memory pub/sub broker with durable per-subscription queues."""
    def __init__(self):
        self.subscriptions = defaultdict(dict)   # topic -> {sub_id: queue}

    def create_topic(self, topic):
        self.subscriptions[topic] = {}

    def subscribe(self, topic, sub_id):
        # Each subscriber gets its own queue (independent copy of messages)
        self.subscriptions[topic][sub_id] = []

    def publish(self, topic, msg):
        # Fan-out: append a copy to every subscriber's queue
        for sub_id, q in self.subscriptions[topic].items():
            q.append(msg)
        print(f"[pub] {topic} -> {len(self.subscriptions[topic])} subscribers")

    def poll(self, topic, sub_id):
        q = self.subscriptions[topic].get(sub_id, [])
        if q:
            return q.pop(0)
        return None

broker = PubSub()
broker.create_topic("video.viewed")
broker.subscribe("video.viewed", "recs")
broker.subscribe("video.viewed", "analytics")
broker.subscribe("video.viewed", "billing")

def subscriber(topic, sub_id, work_ms):
    while True:
        msg = broker.poll(topic, sub_id)
        if msg:
            print(f"[{sub_id}] processing {msg}")
            time.sleep(work_ms / 1000.0)        # independent pace
        else:
            time.sleep(0.01)

# Launch subscribers at different speeds
for sub_id, work in [("recs", 10), ("analytics", 50), ("billing", 20)]:
    threading.Thread(target=subscriber, args=("video.viewed", sub_id, work),
                     daemon=True).start()

# Publish 5 events; each subscriber processes at its own rate
for i in range(5):
    broker.publish("video.viewed", {"video": i, "user": "alice"})
time.sleep(1)
